// Writes the seed corpus for the ELF and `ar` harnesses into a directory:
// fixtures/binscan/SOURCES.md keeps binary blobs out of the repository, so the
// seeds are generated by the same builders the binscan unit tests use.
//
// Usage: fuzz_binary_seed_writer OUTPUT_DIR
//   writes OUTPUT_DIR/elf/*.elf and OUTPUT_DIR/archive/*.a
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <string>

#include "support/archive_builder.hpp"
#include "support/elf_builder.hpp"

namespace fs = std::filesystem;

namespace
{

bool write_seed(const fs::path& path, const std::string& bytes)
{
  std::ofstream stream(path, std::ios::binary);
  stream.write(bytes.data(), static_cast<std::streamsize>(bytes.size()));
  return static_cast<bool>(stream);
}

}  // namespace

int main(int argc, char** argv)
{
  if (argc != 2)
  {
    std::fprintf(stderr, "usage: fuzz_binary_seed_writer OUTPUT_DIR\n");
    return 2;
  }
  const fs::path output(argv[1]);
  std::error_code error;
  fs::create_directories(output / "elf", error);
  fs::create_directories(output / "archive", error);

  bool written = true;

  bomwerk::test::ElfBuildOptions shared_library;
  shared_library.needed = {"libc.so.6", "libssl.so.3", "libz.so.1"};
  shared_library.soname = "libseed.so.1";
  shared_library.exported_symbols = {"seed_init", "seed_run", "seed_shutdown"};
  shared_library.undefined_symbols = {"malloc", "free"};
  written &= write_seed(output / "elf/shared-64-le.elf", bomwerk::test::build_elf(shared_library));

  bomwerk::test::ElfBuildOptions big_endian_32 = shared_library;
  big_endian_32.is_64_bit = false;
  big_endian_32.big_endian = true;
  written &= write_seed(output / "elf/shared-32-be.elf", bomwerk::test::build_elf(big_endian_32));

  bomwerk::test::ElfBuildOptions stripped = shared_library;
  stripped.include_section_headers = false;
  stripped.include_program_headers = true;
  written &= write_seed(output / "elf/stripped-64-le.elf", bomwerk::test::build_elf(stripped));

  bomwerk::test::ElfBuildOptions executable;
  executable.file_type = 2;
  executable.needed = {"libc.so.6"};
  executable.include_program_headers = true;
  written &= write_seed(output / "elf/executable-64-le.elf", bomwerk::test::build_elf(executable));

  bomwerk::test::ElfBuildOptions relocatable;
  relocatable.file_type = 1;
  relocatable.include_dynamic = false;
  written &= write_seed(output / "elf/object-64-le.elf", bomwerk::test::build_elf(relocatable));

  bomwerk::test::ArchiveBuildOptions gnu;
  gnu.members = {{"short.o", "data"}, {"a_member_name_longer_than_sixteen.o", "more data"}};
  gnu.indexed_symbols = {"alpha", "beta", "gamma"};
  written &= write_seed(output / "archive/gnu.a", bomwerk::test::build_archive(gnu));

  bomwerk::test::ArchiveBuildOptions bsd = gnu;
  bsd.bsd_long_names = true;
  bsd.bsd_symbol_index = true;
  written &= write_seed(output / "archive/bsd.a", bomwerk::test::build_archive(bsd));

  bomwerk::test::ArchiveBuildOptions no_index = gnu;
  no_index.include_symbol_index = false;
  no_index.force_long_name_table = true;
  written &= write_seed(output / "archive/no-index.a", bomwerk::test::build_archive(no_index));

  if (!written)
  {
    std::fprintf(stderr, "fuzz_binary_seed_writer: could not write into %s\n",
                 output.string().c_str());
    return 1;
  }
  return 0;
}
